import { tags } from "typia";

import { IPoliticsBbsFileAttachment } from "./IPoliticsBbsFileAttachment";
import { IPoliticsBbsModerator } from "./IPoliticsBbsModerator";

/**
 * Association table for moderator-created image attachments implementing
 * polymorphic ownership pattern. Moderators can upload images for moderation
 * and administrative content.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPoliticsBbsAttachmentOfModerator = {
  /** Primary key. Unique identifier for the moderator attachment association. */
  id: string & tags.Format<"uuid">;

  /** Attachment's ID this subtype belongs to. */
  politics_bbs_attachment_id: string & tags.Format<"uuid">;

  /** Moderator uploader's ID. */
  politics_bbs_moderator_id: string & tags.Format<"uuid">;

  /** Timestamp when moderator uploaded this attachment */
  created_at: string & tags.Format<"date-time">;

  /**
   * Relationship to the main file attachment this moderator upload belongs
   * to.
   */
  attachment?: IPoliticsBbsFileAttachment | undefined;

  /** Relationship to the moderator who uploaded this attachment. */
  moderator?: IPoliticsBbsModerator | undefined;
};
